def f(inp):
    bar=[r for r in range(len(inp)) if all(x==5 for x in inp[r])][0]
    H=len(inp)-bar-1
    topcomps=[]
    for c in range(2,10):
        pl=[(r,j) for r in range(bar) for j in range(len(inp[0])) if inp[r][j]==c]
        for cp in comps8(pl): topcomps.append((cp,c))
    surv=max(topcomps,key=lambda o:(o[1],max(p[1] for p in o[0])))[0]
    lower=[v for r in inp[bar+1:] for v in r if v!=0 and v!=5]
    from collections import Counter
    kc=Counter(lower).most_common(1)[0][0]
    bot=comps8([(r,j) for r in range(bar+1,len(inp)) for j in range(len(inp[0])) if inp[r][j]==kc])[0]
    out=[[0]*len(inp[0]) for _ in range(H)]
    for bi,bj in bot: out[bi-bar-1][bj]=kc
    kt=min(r for r,_ in bot)
    smin=min(r for r,_ in surv)
    sr=kt-bar-1-(max(r for r,_ in surv)-smin)
    ksc=(min(j for _,j in bot)+max(j for _,j in bot))/2
    sc=min(j for _,j in surv); ec=max(j for _,j in surv)
    soff=int(round(ksc-(sc+ec)/2))
    for r,cj in surv:
        rr=sr+(r-smin)
        cc=sc+soff+(cj-sc)
        out[rr][cc]=inp[r][cj]
    return out
